namespace AssetFlow.Agent;
public sealed class Worker:BackgroundService{private readonly AgentClient client;private readonly AgentState state;private readonly InventoryCollector collector;private readonly UpdateService updater;private readonly ILogger<Worker> log;public Worker(AgentClient c,AgentState s,InventoryCollector i,UpdateService u,ILogger<Worker> l){client=c;state=s;collector=i;updater=u;log=l;}protected override async Task ExecuteAsync(CancellationToken ct){while(string.IsNullOrEmpty(state.Options.DeviceToken)&&!ct.IsCancellationRequested){try{await client.EnsureRegistered(ct);log.LogInformation("Agent registration completed for {Machine}",Environment.MachineName);}catch(Exception e){log.LogError(e,"Initial registration failed; retrying in one minute");await Task.Delay(TimeSpan.FromMinutes(1),ct);}}await Task.WhenAll(CollectionLoop(ct),HeartbeatLoop(ct),UpdateLoop(ct));}private async Task CollectionLoop(CancellationToken ct){while(!ct.IsCancellationRequested){try{await client.SendInventory(await collector.CollectAsync(),ct);log.LogInformation("Inventory sent at {Time}",DateTimeOffset.Now);}catch(Exception e){log.LogError(e,"Collection failed; retrying later");}await Task.Delay(TimeSpan.FromMinutes(Math.Max(5,state.Options.CollectionMinutes)),ct);}}private async Task HeartbeatLoop(CancellationToken ct){while(!ct.IsCancellationRequested){try{await client.Heartbeat(ct);log.LogInformation("Heartbeat sent at {Time}",DateTimeOffset.Now);}catch(Exception e){log.LogError(e,"Heartbeat failed; retrying later");}await Task.Delay(TimeSpan.FromMinutes(5),ct);}}private async Task UpdateLoop(CancellationToken ct){while(!ct.IsCancellationRequested){try{await updater.CheckAndApply(ct);}catch(Exception e){log.LogError(e,"Update check failed; retrying later");}await Task.Delay(TimeSpan.FromMinutes(Math.Max(5,state.Options.UpdateCheckMinutes)),ct);}}}
